import pathlib,json,html
out=pathlib.Path('docs/mission-23-evidence');before=json.loads((out/'before.json').read_text());after=json.loads((out/'after.json').read_text());pairs=[]
for b in before['rows']:
 a=next(r for r in after['rows'] if r['name']==b['name'])
 if b['state']['camera']!=a['state']['camera']:raise ValueError('Unmatched camera: '+b['name'])
 pairs.append({'name':b['name'],'before':b['state'],'after':a['state'],'ground':a['ground']})
videos=[('pont-native','Pont, raccord, montée/descente et retour en course'),('pente-marche-course','Pente : marche, arrêt, descente et course'),('escalier-documente','Axe OSM d’escalier ; géométrie des marches non relevée'),('sentier-neige','Sentier sous neige, dépôt verrouillé pour le diagnostic'),('raccord-arret-reprise','Raccord : arrêt et reprise'),('rotation-camera','Rotation de caméra au repos'),('mobile-native','Commandes tactiles natives'),('walk-opening','Promenade prolongée — extrait initial'),('walk-night','Promenade prolongée — nuit'),('walk-storm','Promenade prolongée — météo')]
cards=''.join(f'<article><h3>{html.escape(label)}</h3><video controls preload="metadata" src="{name}.webm"></video></article>' for name,label in videos if (out/(name+'.webm')).exists())
body='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Endless Earth — Mission 23</title><style>
*{box-sizing:border-box}body{margin:0;background:#17241f;color:#eee9dd;font:16px/1.55 system-ui}main{max-width:1400px;margin:auto;padding:24px}h1{font-size:clamp(26px,4vw,46px);font-weight:500}h2{margin-top:36px;font-weight:500}a{color:#bbdac6}button,select{font:inherit;padding:10px;margin:8px 8px 8px 0;background:#e3e1d2;color:#173126;border:0;border-radius:5px;max-width:100%}.pair,.movies{display:grid;grid-template-columns:1fr 1fr;gap:18px}figure{margin:0}img,video{width:100%;display:block;background:#101813}figcaption{padding:8px 0}.note{padding:16px;border-left:4px solid #d3b56d;background:#26372e}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}article{background:#22342a;padding:14px;border-radius:8px}ul{padding-left:22px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:9px;border-bottom:1px solid #45574c;text-align:left}@media(max-width:760px){main{padding:14px}.pair,.movies{grid-template-columns:1fr}}
</style><main><p>Endless Earth · preuves du moteur</p><h1>Mission 23 — La vérité du terrain</h1>
<p class="note">Les sept captures originales du propriétaire sont absentes de cette session. Aucune n’est déclarée retrouvée ou corrigée. Les scènes ci-dessous sont des stations de contrôle issues des données géographiques. Les grandes falaises et limites conservées restent visibles.</p>
<p>24 paires natives · caméra, date, heure, profil et résolution appariés · 12 scènes avec et sans neige. Dépôt de neige verrouillé à 0/1 pour isoler son effet. Aucun concept graphique ni retouche.</p>
<label for="scene">Scène</label><select id="scene"></select><div class="pair"><figure><img id="before" alt="Référence Mission 22.1"><figcaption>Avant · Mission 22.1 fusionnée, 6b17ce3</figcaption></figure><figure><img id="after" alt="Mission 23"><figcaption>Après · géométrie source et support commun</figcaption></figure></div><details><summary>Caméra, climat, support et provenance</summary><pre id="metadata"></pre></details>
<h2>Films natifs</h2><p>Chaque film de parcours possède une pose initiale déclarée. Les déplacements suivants utilisent le vrai contrôleur au clavier ou au tactile. Les extraits prolongés et les scénarios complémentaires sont distingués dans le rapport.</p><div class="movies">'''+cards+'''</div><h2>Audits et mesures</h2><ul>
<li><a href="../mission-23.md">Rapport et tableau d’acceptation</a></li><li><a href="owner-cases/cases.json">Les sept cas non vérifiables</a></li><li><a href="source-audit.json">Comparaison avec le MNT natif</a> · <a href="mnt-sources.json">Sources et droits</a></li><li><a href="geometry-before.json">Inventaire avant</a> · <a href="geometry-after.json">Inventaire après</a></li><li><a href="network-audit.json">Axes et parcours physiques</a></li><li><a href="performance.json">Benchmarks appariés, trois profils</a></li><li><a href="walk.json">Promenade native prolongée</a></li><li><a href="routes-native.json">Parcours natifs complémentaires</a> · <a href="pont-native.json">Pont</a> · <a href="mobile.json">Tactile</a></li></ul><p>Chromium / SwiftShader logiciel. Aucun résultat Android ou GPU physique n’est revendiqué. Les reconstructions ne constituent pas un relevé absolu du site.</p></main><script>const pairs='''+json.dumps(pairs,separators=(',',':')).replace('</','<\\/')+''';const select=document.querySelector('#scene');for(const [i,p]of pairs.entries()){const option=document.createElement('option');option.value=i;option.textContent=p.name;select.append(option)}function show(){const p=pairs[select.value||0];document.querySelector('#before').src='before/'+p.name+'.png';document.querySelector('#after').src='after/'+p.name+'.png';document.querySelector('#metadata').textContent=JSON.stringify(p,null,2)}select.addEventListener('change',show);show();</script></html>'''
(out/'index.html').write_text(body)
(out/'gallery-scenes.json').write_text(json.dumps({'pairs':len(pairs),'cameraMatched':True,'scenes':[p['name'] for p in pairs],'videos':[name+'.webm' for name,_ in videos if (out/(name+'.webm')).exists()]},indent=2)+'\n')
print('Gallery',len(pairs),'pairs')
